ALTER TABLE "agent_wakeup_requests" ADD COLUMN "continuation_key" text;--> statement-breakpoint
-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable because this partial index must exist atomically before the first continuation-key wake is written (at-most-once continuation per key). The predicate matches zero pre-migration rows — continuation_key is NULL on all existing rows — so the build only scans without indexing existing tuples.
CREATE UNIQUE INDEX "agent_wakeup_requests_continuation_key_uq" ON "agent_wakeup_requests" USING btree ("company_id","agent_id","continuation_key") WHERE "agent_wakeup_requests"."continuation_key" IS NOT NULL AND "agent_wakeup_requests"."status" <> 'skipped';
